css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-ba{width:min(860px,100%);display:grid;gap:1.2em}
.fx-ba .top{display:flex;justify-content:space-between;align-items:end;gap:1em;flex-wrap:wrap}
.fx-ba h2{font-size:clamp(1.8em,4vw,2.6em)}.fx-ba .top p{opacity:.6;font-size:.92em}
.fx-ba .ba{--pos:50%;position:relative;aspect-ratio:16/10;border-radius:var(--radius);overflow:hidden;touch-action:pan-y;cursor:ew-resize;user-select:none;isolation:isolate}
.fx-ba .layer{position:absolute;inset:0}
.fx-ba .before{clip-path:inset(0 calc(100% - var(--pos)) 0 0);filter:grayscale(1) contrast(.85) brightness(1.08)}
.fx-ba .tagl{position:absolute;top:1em;padding:.35em .85em;border-radius:99px;font-size:.74em;font-weight:700;letter-spacing:.1em;text-transform:uppercase;background:var(--surface);color:var(--text);z-index:2}
.fx-ba .tl{left:1em}.fx-ba .tr{right:1em}
.fx-ba .bar{position:absolute;top:0;bottom:0;left:var(--pos);width:2px;margin-left:-1px;background:var(--surface);z-index:3;pointer-events:none}
.fx-ba .knob{position:absolute;top:50%;left:50%;width:2.8em;height:2.8em;margin:-1.4em 0 0 -1.4em;border-radius:50%;background:var(--surface);color:var(--text);display:grid;place-items:center;font-weight:700;box-shadow:0 6px 20px rgba(0,0,0,.28);transition:transform calc(.25s/var(--speed))}
.fx-ba .ba:hover .knob{transform:scale(1.08)}
.fx-ba input{position:absolute;inset:0;width:100%;height:100%;opacity:0;margin:0;pointer-events:none}
.fx-ba input:focus-visible~.bar .knob{outline:3px solid var(--accent);outline-offset:3px}
.fx-ba .cap{display:flex;justify-content:space-between;gap:1em;font-size:.88em;opacity:.65}
@media(max-width:480px){.fx-ba .ba{aspect-ratio:4/3}}
@media(prefers-reduced-motion:reduce){.fx-ba .knob{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-ba .ba.is-tap .knob{transform:scale(1.08)}

js:
(function(){document.querySelectorAll('.fx-ba .ba').forEach(function(b){var inp=b.querySelector('input'),drag=false;
function set(p){p=Math.max(0,Math.min(100,p));b.style.setProperty('--pos',p+'%');inp.value=p}
function fromX(x){var r=b.getBoundingClientRect();set((x-r.left)/r.width*100)}
b.addEventListener('pointerdown',function(e){drag=true;try{b.setPointerCapture(e.pointerId)}catch(_){}fromX(e.clientX)});
b.addEventListener('pointermove',function(e){if(drag)fromX(e.clientX)});
['pointerup','pointercancel'].forEach(function(n){b.addEventListener(n,function(){drag=false})});
inp.addEventListener('input',function(){set(+inp.value)});
b.setAttribute('role','group')})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
